from collections import Counter

def transform(grid):
    out=[row[:] for row in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r,row in enumerate(grid):
        active=[c for c,v in enumerate(row) if v!=bg]
        if not active:
            continue
        end=max(active)
        # Recolor the background tail after the rightmost foreground mark.
        for c in range(end+1,len(row)):
            if row[c]==bg:
                out[r][c]=1
    return out

